  // Logika spec var representing port state for outgoing data port
  @spec var dock_facts: Mining_Cargo_Transfer_Evidence_Coordinator.DockFacts = $

  def put_dock_facts(value : Mining_Cargo_Transfer_Evidence_Coordinator.DockFacts) : Unit = {
    Contract(
      Modifies(dock_facts),
      Ensures(
        dock_facts == value
      )
    )
    Spec {
      dock_facts = value
    }

    Art.putValue(dock_facts_Id, Mining_Cargo_Transfer_Evidence_Coordinator.DockFacts_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class DockContextAssessment_Initialization_Api (
  val id: Art.BridgeId,
  val dock_context_Id : Art.PortId,
  val dock_facts_Id : Art.PortId) extends DockContextAssessment_Api

@datatype class DockContextAssessment_Operational_Api (
